const icon = (name, size = 18) => {
  const common = `width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"`;
  const icons = {
    search: `<svg ${common}><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4.5 4.5"></path></svg>`,
    phone: `<svg ${common}><path d="M21 16.9v2.2a1.8 1.8 0 0 1-2 1.8A17.8 17.8 0 0 1 2.7 5a1.8 1.8 0 0 1 1.8-2H6.8A1.8 1.8 0 0 1 8.6 4.5c.1 1 .4 2 .8 2.9a1.8 1.8 0 0 1-.4 1.9L8 10.4a14 14 0 0 0 5.6 5.6l1.1-1.1a1.8 1.8 0 0 1 1.9-.4c.9.4 1.9.7 2.9.8A1.8 1.8 0 0 1 21 16.9Z"></path></svg>`,
    arrow: `<svg ${common}><path d="M5 12h14"></path><path d="m13 6 6 6-6 6"></path></svg>`,
    chevron: `<svg ${common}><path d="m9 18 6-6-6-6"></path></svg>`,
    heart: `<svg ${common}><path d="M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.9-8.6a5.5 5.5 0 0 0-.1-7.8Z"></path></svg>`,
    check: `<svg ${common}><path d="m5 12 4 4L19 6"></path></svg>`,
    shield: `<svg ${common}><path d="M12 3 4.5 6.5v5.4c0 4.6 3.2 7.5 7.5 9.1 4.3-1.6 7.5-4.5 7.5-9.1V6.5L12 3Z"></path><path d="m8.5 12 2.2 2.2 4.8-4.8"></path></svg>`,
    clock: `<svg ${common}><circle cx="12" cy="12" r="8.5"></circle><path d="M12 7v5l3.4 2"></path></svg>`,
    calendar: `<svg ${common}><rect x="3.5" y="5" width="17" height="15" rx="2"></rect><path d="M7.5 3v4M16.5 3v4M3.5 10h17"></path></svg>`,
    user: `<svg ${common}><circle cx="12" cy="8" r="3.3"></circle><path d="M5.5 20c.6-3.4 2.7-5.2 6.5-5.2s5.9 1.8 6.5 5.2"></path></svg>`,
    location: `<svg ${common}><path d="M20 10c0 5-8 11-8 11S4 15 4 10a8 8 0 1 1 16 0Z"></path><circle cx="12" cy="10" r="2.4"></circle></svg>`,
    hospital: `<svg ${common}><path d="M4 21V5.5A1.5 1.5 0 0 1 5.5 4h13A1.5 1.5 0 0 1 20 5.5V21"></path><path d="M9 21v-4h6v4M8 8h1M15 8h1M8 12h1M15 12h1M12 7v4M10 9h4"></path></svg>`,
    plus: `<svg ${common}><path d="M12 5v14M5 12h14"></path></svg>`,
    upload: `<svg ${common}><path d="M12 16V4"></path><path d="m7 9 5-5 5 5"></path><path d="M5 20h14"></path></svg>`,
    play: `<svg ${common} fill="currentColor" stroke="none"><path d="m9 7 8 5-8 5V7Z"></path></svg>`,
    menu: `<svg ${common}><path d="M4 7h16M4 12h16M4 17h16"></path></svg>`,
    close: `<svg ${common}><path d="m6 6 12 12M18 6 6 18"></path></svg>`,
    star: `<svg ${common} fill="currentColor"><path stroke="none" d="m12 3 2.6 5.3 5.8.8-4.2 4.1 1 5.8-5.2-2.7L6.8 19l1-5.8L3.6 9.1l5.8-.8L12 3Z"></path></svg>`,
    info: `<svg ${common}><circle cx="12" cy="12" r="8.5"></circle><path d="M12 11v5M12 8h.01"></path></svg>`,
  };
  return icons[name] || icons.info;
};

const button = (label, href, kind = 'primary-btn', extra = '') => `<a class="${kind}" href="${href}" ${extra}>${label}</a>`;

function siteHeader(active = '') {
  const nav = [
    ['Doctors', routes.doctors, 'doctors'],
    ['Departments', routes.departments, 'departments'],
    ['About', routes.about, 'about'],
    ['Blogs', routes.blogs, 'blogs'],
  ];
  return `
    <header class="sub-header">
      <div class="amz-wrap sub-header__bar">
        <a class="sub-logo" href="${routes.home}" aria-label="AMZ Hospital home"><img src="assets/images/amz-logo.png" alt="AMZ Hospital Ltd." /></a>
        <nav class="sub-nav" aria-label="Primary navigation">
          ${nav.map(([label, href, key]) => `<a href="${href}" ${active === key ? 'aria-current="page"' : ''}>${label}</a>`).join('')}
        </nav>
        <div class="sub-header__actions">
          <button class="sub-search" type="button" data-search-trigger aria-label="Search AMZ Hospital">${icon('search', 16)}<span>Search</span></button>
          <div class="sub-language" aria-label="Language selection"><span class="font-bengali">বাংলা</span><span>English</span></div>
          <a class="sub-hotline" href="tel:10699">${icon('phone', 16)}Hot Line-10699</a>
        </div>
        <button class="sub-menu-toggle" type="button" aria-expanded="false" aria-controls="sub-mobile-menu" aria-label="Open navigation menu">${icon('menu', 21)}</button>
      </div>
      <nav class="sub-mobile-menu" id="sub-mobile-menu" aria-label="Mobile navigation">
        ${nav.map(([label, href, key]) => `<a href="${href}" ${active === key ? 'aria-current="page"' : ''}>${label}</a>`).join('')}
        <a class="sub-hotline" href="tel:10699">${icon('phone', 16)}Hot Line-10699</a>
      </nav>
    </header>`;
}

