function crumbs(items) {
  return `<nav class="crumbs" aria-label="Breadcrumb">${items.map((item, index) => `${index ? icon('chevron', 12) : ''}${item.href ? `<a href="${item.href}">${item.label}</a>` : `<span>${item.label}</span>`}`).join('')}</nav>`;
}

function faq(items) {
  return `<div class="faq-list" data-accordion>${items.map((item, index) => `<div class="faq-item ${index === 0 ? 'is-open' : ''}"><button type="button" aria-expanded="${index === 0}"><span>${item[0]}</span><span>+</span></button><div class="faq-item__answer">${item[1]}</div></div>`).join('')}</div>`;
}

