function articlePage() {
  const related = [
    ['blog-related-1.jpg', 'Understanding Cholesterol: What Your Numbers Mean'],
    ['blog-related-2.jpg', 'How to Build a Heart-Healthy Routine'],
    ['blog-related-3.jpg', 'When Should You Speak to a Cardiologist?'],
  ];
  return `
    <section class="amz-wrap">${crumbs([{ label: 'Home', href: routes.home }, { label: 'Health Journal', href: routes.blogs }, { label: 'Heart Health' }])}<div class="article-layout"><article><span class="article-category">HEART HEALTH · 6 MIN READ</span><h1 class="article-title">Your Heart, Your Health: A Practical Guide to Preventive Care</h1><div class="article-byline"><img src="assets/images/pages/blog-author.jpg" alt="Dr. Amara Okafor" /><span><b>Dr. Amara Okafor</b><br />Consultant Cardiologist, AMZ Hospital</span><span>Updated June 20, 2025</span></div><img class="article-hero-image" src="assets/images/pages/blog-heart-hero.jpg" alt="Heart health preventive care" /><div class="article-content"><p>Heart health is built through small choices, regular attention and knowing when it is time to speak with a specialist. This guide offers simple, practical information to help you understand preventive heart care and feel more confident about your next step.</p><div class="article-disclaimer">${icon('info', 15)} <b>Important:</b> This article is for general health education only. It does not replace advice, diagnosis or treatment from a qualified medical professional.</div><h2>Why Preventive Heart Care Matters</h2><p>Cardiovascular conditions can develop quietly over time. Regular check-ins, a clear understanding of your personal risk and sustainable daily habits can all play a role in protecting long-term heart health. Preventive care is not about worry; it is about giving yourself useful information and a practical plan.</p><h2>Know Your Personal Risk Factors</h2><p>Risk factors can include high blood pressure, high cholesterol, diabetes, smoking, low physical activity, family history and age. Some can be changed, while others simply help a doctor understand the right level of support for you.</p><p>If you have a family history of heart disease or notice a change in your usual wellbeing, it can be helpful to arrange a consultation and discuss what screening may be appropriate.</p><h2>Small Habits That Support Heart Health</h2><p>Focus on steady, sustainable changes: move your body regularly, eat a balanced diet rich in vegetables and fibre, sleep well, reduce tobacco exposure and find healthy ways to manage stress. A healthcare professional can help adapt these steps to your own medical history.</p><h2>When to Speak With a Specialist</h2><p>Seek expert guidance if you have persistent chest discomfort, unusual shortness of breath, palpitations, fainting, or symptoms that concern you. For severe or sudden symptoms, seek emergency medical care immediately.</p><h2>Preparing for Your Appointment</h2><p>Bring any past medical reports, a list of current medications and questions you would like to discuss. Sharing a full picture helps your doctor understand your needs and discuss a clear next step.</p></div></article><aside class="article-aside"><div class="toc"><h2>In this guide</h2><a href="#">Why preventive care matters</a><a href="#">Know your risk factors</a><a href="#">Small habits that help</a><a href="#">When to speak with a specialist</a><a href="#">Preparing for your visit</a></div><div class="aside-reviewer"><img src="assets/images/pages/blog-reviewer.jpg" alt="Medical reviewer" /><strong>Medically reviewed by AMZ Hospital</strong><span>Reviewed by a relevant clinical professional for clarity and patient safety.</span>${button('Find a Cardiologist', routes.doctors, 'primary-btn')}</div></aside></div></section>
    <section class="page-section page-section--tint"><div class="amz-wrap"><div class="section-heading"><div><span class="section-kicker">Keep learning</span><h2 class="section-title-new">Related Health Guides</h2></div><a class="quiet-link" href="${routes.blogs}">View all resources ${icon('arrow', 14)}</a></div><div class="news-grid">${related.map(([img, title]) => `<article class="news-card"><img src="assets/images/pages/${img}" alt="${title}" /><div class="news-card__body"><small>HEART HEALTH</small><h3>${title}</h3><span>5 min read</span><br /><a class="quiet-link" style="margin-top:15px;display:inline-flex" href="#">Read Guide ${icon('arrow', 13)}</a></div></article>`).join('')}</div></div></section>
    <section class="page-section page-section--warm"><div class="amz-wrap"><div class="final-cta"><div><span class="section-kicker">Your next step</span><h2 class="section-title-new">Need Expert Heart Care?</h2><p class="section-copy">Connect with an AMZ cardiology specialist for a clear, confident next step.</p></div><div class="final-cta__actions">${button('Find a Specialist', routes.doctors, 'primary-btn')}${button('Book Appointment', routes.appointment, 'outline-btn')}</div></div></div></section>`;
}

